[ExtensionOf(formStr(GUPPriceRebatePriceAttributeGroupEdit))]
internal final class METGUPPriceRebatePriceAttributeGroupEdit_Extension
{
    internal TAMRebateDeal rebateDeal;
    internal boolean isCloseOk;
}

Method.Source:
/// <summary>
/// Perform actions at form init
/// </summary>
public void init()
{
    next init();

    TAMRebateTable callerRecord;

    if (this.args().record() && this.args().dataset() == tableNum(TAMRebateTable))
    {
        callerRecord = this.args().record();
        rebateDeal = TAMRebateDeal::find(callerRecord.RebateDeal);
    }
}

public void closeOK()
{
    isCloseOk = true;

    next closeOK();
}

/// <summary>
/// Price attribute details validation performed when form gets closed.
/// </summary>
public void close()
{
    FormRun formRun = this;

    if (isCloseOk && rebateDeal.METVolumetricTierDeal == NoYes::Yes && formRun.args().record() && formRun.args().dataset() == tableNum(TAMRebateTable))
    {
        TAMRebateTable callerRecord;
        TAMRebateTable tamRebateTable;

        callerRecord = formRun.args().record();

        select firstonly tamRebateTable
            where tamRebateTable.RebateId != callerRecord.RebateId
            && tamRebateTable.RebateDeal == rebateDeal.RecId;

        if (tamRebateTable.RecId && tamRebateTable.pricingAttributeDetailsHeader() != callerRecord.pricingAttributeDetailsHeader())
        {
            callerRecord.dataSource().reread();
            throw error(strFmt("@MET:NoMatchingPriceAttributes"));
        }
    }

    next close();
}
